// Self-healing index page: detect checksum mismatch, repair from replica
function sum(s){let h=0;for(const ch of s)h=(h*31+ch.charCodeAt(0))>>>0;return h;}
const good='"indx-healthy-page-7"';
const page={id:7,data:'"indx-corrupt"',storedSum:sum(good)};
const replica={id:7,data:good};
if(sum(page.data)!==page.storedSum){console.log('page '+page.id+' corrupt -> repaired from replica');page.data=replica.data;}
console.log('page '+page.id+' healthy:',sum(page.data)===page.storedSum);

